"""Output plumbing shared by every `bip` command.

Plain-English picture: this module is the CLI's mouth. Commands compute
plain Python dictionaries and lists; this decides whether a human sees a
coloured Rich table or a machine sees JSON. Keeping that decision in one
place is what lets `--json` and `--quiet` work everywhere without each
command reimplementing them.

Nothing here does science. It formats what the pipeline already computed.
"""

from __future__ import annotations

import json
import os
import sys
from dataclasses import dataclass, field
from typing import Any, Iterable, Sequence

from rich.console import Console
from rich.table import Table
from rich.text import Text

def _force_utf8() -> None:
    """Make stdout/stderr UTF-8 where the platform allows it.

    Windows consoles still default to cp1252, which cannot encode the ▲/▼
    markers or an em dash. Reconfiguring is the fix; `supports_unicode` below
    is the fallback for the cases where it isn't possible (a redirected pipe
    under an exotic codepage, say).
    """
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")  # type: ignore[union-attr]
        except (AttributeError, OSError, ValueError):
            pass


def supports_unicode() -> bool:
    encoding = getattr(sys.stdout, "encoding", None) or "ascii"
    try:
        "▲▼·—".encode(encoding)
    except (LookupError, UnicodeEncodeError):
        return False
    return True


_force_utf8()
_UNICODE = supports_unicode()

# Printed verbatim by any command that shows model predictions. The wording is
# fixed by docs/cli.md — do not paraphrase it.
FOOTER = (
    "research output — paper only, not investment advice"
    if _UNICODE
    else "research output - paper only, not investment advice"
)

# Meaning must survive --no-color, so direction is carried by a symbol as well
# as a colour. ASCII fallbacks keep that true on a cp1252 console.
UP = "▲" if _UNICODE else "^"
DOWN = "▼" if _UNICODE else "v"
FLAT = "·" if _UNICODE else "-"


def dash(text: str) -> str:
    """Em dashes are decorative; downgrade them rather than crash."""
    return text if _UNICODE else text.replace("—", "-")


@dataclass
class Ctx:
    """Global flags, resolved once in the Typer callback and passed down."""

    json_out: bool = False
    quiet: bool = False
    no_color: bool = False
    debug: bool = False
    cfg: dict[str, Any] = field(default_factory=dict)

    @property
    def console(self) -> Console:
        # no_color strips ANSI styling; quiet additionally implies no colour so
        # that piped/CI output is plain text either way.
        return Console(
            no_color=self.no_color or self.quiet,
            highlight=False,
            soft_wrap=True,
        )

    @property
    def mascot_enabled(self) -> bool:
        """Blip appears only for an interactive human who hasn't opted out."""
        if self.json_out or self.quiet:
            return False
        if os.environ.get("BIP_NO_MASCOT"):
            return False
        return sys.stdout.isatty()


def fmt(value: Any, sig: int = 4) -> str:
    """Format a number to `sig` significant figures; pass everything else through."""
    if value is None:
        return "-"
    if isinstance(value, bool):
        return "yes" if value else "no"
    if isinstance(value, (int,)) and not isinstance(value, bool):
        return f"{value:,}"
    if isinstance(value, float):
        if value != value:  # NaN
            return "nan"
        if value == 0:
            return "0"
        return f"{value:#.{sig}g}"
    return str(value)


def direction(value: float | None) -> str:
    """A sign marker that still reads correctly with colour disabled."""
    if value is None or value != value:
        return FLAT
    if value > 0:
        return UP
    if value < 0:
        return DOWN
    return FLAT


def signed(value: float | None, sig: int = 4) -> Text:
    """Number prefixed with ▲/▼ and coloured, for delta-style columns."""
    marker = direction(value)
    body = f"{marker} {fmt(value, sig)}"
    if value is None or value != value or value == 0:
        return Text(body)
    return Text(body, style="green" if value > 0 else "red")


def build_table(
    title: str,
    columns: Sequence[str],
    rows: Iterable[Sequence[Any]],
    numeric: Sequence[str] = (),
    keep_whole: Sequence[str] = (),
) -> Table:
    """A Rich table with numbers right-aligned and values at 4 sig figs.

    `numeric` names the columns that should be right-aligned; everything else
    is left-aligned. `keep_whole` names columns that must never be truncated
    with an ellipsis — identifiers stay readable, prose wraps instead.
    """
    table = Table(title=dash(title), title_justify="left", header_style="bold")
    for name in columns:
        table.add_column(
            dash(name),
            justify="right" if name in numeric else "left",
            no_wrap=name in numeric,
            overflow="fold" if name in keep_whole else "ellipsis",
        )
    for row in rows:
        table.add_row(
            *[cell if isinstance(cell, Text) else dash(fmt(cell)) for cell in row]
        )
    return table


def emit(
    ctx: Ctx,
    payload: dict[str, Any],
    table: Table | None = None,
    footer: bool = False,
) -> None:
    """The single output call.

    `payload` is the machine-readable truth; `table` is the human rendering of
    the same numbers. Under --json only the payload is printed, so the two must
    never disagree.
    """
    if ctx.json_out:
        json.dump(payload, sys.stdout, indent=2, default=str)
        sys.stdout.write("\n")
        return

    console = ctx.console
    if table is not None:
        console.print(table)
    if footer:
        console.print(FOOTER, style="dim")


def say(ctx: Ctx, message: str, style: str = "") -> None:
    """Human-only progress chatter. Silent under --json and --quiet."""
    if ctx.json_out or ctx.quiet:
        return
    ctx.console.print(message, style=style)

"""Plain-English error handling for the CLI.

Plain-English picture: when something breaks, a researcher wants one sentence
telling them what to do next — not forty lines of Python traceback. The
`guarded` decorator wraps every command so that failures print a readable
explanation, and the traceback appears only when you ask for it with --debug.
"""

from __future__ import annotations

import functools
from typing import Any, Callable

import typer

from bipgpt.cli.console import Ctx


class BipError(Exception):
    """An error we anticipated and can explain in one sentence.

    Raise this (rather than a bare Exception) whenever the CLI knows both what
    went wrong and what the user should do about it. `hint` is printed as the
    suggested next step.
    """

    def __init__(self, message: str, hint: str | None = None) -> None:
        super().__init__(message)
        self.hint = hint


# Exceptions the pipeline raises that we can translate without a traceback.
# Maps exception class name -> suggested next step.
_KNOWN_HINTS = {
    "TestSplitLockout": "pass --i-know-this-is-the-one-shot if you really mean it",
    "LeakageError": "the data store failed a leakage check — do not use these results",
    "FileNotFoundError": "run `bip status` to see which tables exist",
    "ModuleNotFoundError": "run `uv sync` to install the project's dependencies",
}


def _ctx_from(args: tuple[Any, ...]) -> Ctx:
    """Dig the Ctx out of the Typer context, falling back to defaults."""
    for arg in args:
        if isinstance(arg, typer.Context) and isinstance(arg.obj, Ctx):
            return arg.obj
    return Ctx()


def guarded(fn: Callable) -> Callable:
    """Wrap a command so errors print plain English and exit non-zero."""

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any):
        ctx = _ctx_from(args)
        try:
            return fn(*args, **kwargs)
        except (typer.Exit, typer.Abort):
            raise
        except Exception as exc:  # noqa: BLE001 - deliberate top-level handler
            if ctx.debug:
                raise
            _report(ctx, exc)
            raise typer.Exit(code=1) from exc

    return wrapper


def _report(ctx: Ctx, exc: Exception) -> None:
    """Print the apology, the one-line cause, and the suggested next step."""
    from bipgpt.cli import blip

    console = ctx.console
    hint = getattr(exc, "hint", None) or _KNOWN_HINTS.get(type(exc).__name__)

    if ctx.mascot_enabled:
        # Blip apologises first, then gets out of the way. Whimsy never
        # replaces the error text.
        console.print(blip.render("dizzy"), style="yellow")

    if isinstance(exc, BipError):
        # We anticipated this one: the message IS the explanation, and its
        # traceback points at our own raise statement, so don't advertise it.
        console.print(str(exc), style="bold red")
    else:
        console.print(f"{type(exc).__name__}: {exc}", style="bold red")

    if hint:
        console.print(f"try: {hint}", style="dim")
    if not ctx.debug and not isinstance(exc, BipError):
        console.print("re-run with --debug for the full traceback", style="dim")

